def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    mask = (1 << n) - 1

    def rot(b: int, k: int) -> int:
        k %= n
        if k == 0:
            return b
        return ((b << k) | (b >> (n - k))) & mask

    def mul(a: int, b: int) -> int:
        # Cyclic convolution over GF(2), i.e. multiplication mod (x^n - 1).
        res = 0
        i = 0
        while a:
            if a & 1:
                res ^= rot(b, i)
            a >>= 1
            i += 1
        return res

    # Characteristic polynomial of one step: lamp i takes old[i + d],
    # so each offset d contributes x^((-d) mod n). Toggling with XOR
    # makes duplicate offsets cancel.
    q = 0
    for d in offsets:
        q ^= 1 << ((-d) % n)

    s = 0
    for i, c in enumerate(state):
        if c == '1':
            s |= 1 << i

    # Apply q^t to the state by binary exponentiation.
    while t:
        if t & 1:
            s = mul(q, s)
        t >>= 1
        if t:
            q = mul(q, q)

    return ''.join('1' if (s >> i) & 1 else '0' for i in range(n))
